-- District Jewelers Denver (16.11.2026): Other sa poljem za upis na medicinskom pitanju, opisi rezova i settinga za AI (Rickyjevi opisi).
-- Pitanja i opcije se traže po ID-ju i natpisu (json_tree), ne po poziciji: forma se mogla mijenjati u builderu. Nađe li se ništa, ništa se ne mijenja.
-- Prethodna verzija ostaje u History (form_versions).
INSERT INTO form_versions (id, form_id, data, saved_at)
  SELECT 'mig15district', id, data, updated_at FROM forms WHERE id = 'district-jewelers-denver-enrique-gon-cus';

-- Medicinsko/zubno stanje: izbor "Other" i kupac upiše svoje.
UPDATE forms SET data = json_set(data, (SELECT t.path FROM json_tree(forms.data) t WHERE t.key = 'id' AND t.atom = 'grillz_any_previous_or_existing_medical_' AND t.path LIKE '$.steps[%].fields[%]' AND t.path NOT LIKE '%.options%') || '.writeIn', json('true'))
  WHERE id = 'district-jewelers-denver-enrique-gon-cus' AND (SELECT t.path FROM json_tree(forms.data) t WHERE t.key = 'id' AND t.atom = 'grillz_any_previous_or_existing_medical_' AND t.path LIKE '$.steps[%].fields[%]' AND t.path NOT LIKE '%.options%') IS NOT NULL;

-- Opisi rezova za AI (prikazuju se i u builderu kao AI note).
UPDATE forms SET data = json_set(data, (SELECT o.path FROM json_tree(forms.data) o WHERE o.key = 'label' AND o.atom = 'Polished' AND o.path LIKE (SELECT t.path FROM json_tree(forms.data) t WHERE t.key = 'id' AND t.atom = 'grillz_grill_cut' AND t.path LIKE '$.steps[%].fields[%]' AND t.path NOT LIKE '%.options%') || '.options[%]') || '.note', 'polished: plain high-polish mirror look on every cap, smooth metal with no engraving')
  WHERE id = 'district-jewelers-denver-enrique-gon-cus' AND (SELECT o.path FROM json_tree(forms.data) o WHERE o.key = 'label' AND o.atom = 'Polished' AND o.path LIKE (SELECT t.path FROM json_tree(forms.data) t WHERE t.key = 'id' AND t.atom = 'grillz_grill_cut' AND t.path LIKE '$.steps[%].fields[%]' AND t.path NOT LIKE '%.options%') || '.options[%]') IS NOT NULL;
